// Общие шаги для нескольких бизнесов (#04d339). Только просмотр: ничего не создаётся и не меняется,
// JobDetail только открывается (автосохранение — в форме ничего не трогаем).
// Каждый тест в конце возвращает бизнес «test» (переключатель + localStorage selected-company-id) — restoreTest().
// Не сверено с сайтом при записи (правило проекта — не открывать сайт): роль пунктов выпадающего списка
// переключателя (menuitem/option), поиск по клиенту в /jobs и /customers — локаторы с запасными вариантами.
import { expect, Locator, Page } from '@playwright/test';

/** Бизнес «test» — основной тестовый. */
export const TEST_COMPANY = { id: '4432bd2f-3f47-43cf-8ef2-b0c16436f025', name: 'test' } as const;
/** Второй бизнес владельца (18.10, решение пользователя). Только просмотр. */
export const ONSITE_COMPANY = { name: 'Onsite Locksmith' } as const;

/** Данные, созданные пользователем 18.10 в Onsite, и работа из test. */
export const DATA = {
  onsiteClient: 'QA-B2 client',
  onsiteJob: 'JOB-1036',
  onsiteSearch: 'QA-B2',
  testClient: 'QA-quota client',
  testJob: { code: 'JOB-0094', id: '854ea3bb-134d-4c1b-b0a4-a0419854f1f6' },
} as const;

const esc = (s: string) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const COMPANY_NAMES = new RegExp(`^\\s*(${esc(TEST_COMPANY.name)}|${esc(ONSITE_COMPANY.name)})\\s*$`);

/**
 * Язык EN — всегда; бизнес «test» — только при первой загрузке вкладки (флаг в sessionStorage),
 * чтобы переключение бизнеса в тесте не сбрасывалось при переходах.
 */
export async function startInTest(page: Page) {
  await page.addInitScript((company) => {
    try {
      window.localStorage.setItem('preferred-language', 'en');
      if (!window.sessionStorage.getItem('qa-mb-init')) {
        window.localStorage.setItem('selected-company-id', company);
        window.sessionStorage.setItem('qa-mb-init', '1');
      }
    } catch { /* ignore */ }
  }, TEST_COMPANY.id);
}

/** Кнопка переключателя в шапке — её текст = выбранный бизнес. */
export function companySwitcher(page: Page): Locator {
  return page.getByRole('button').filter({ hasText: COMPANY_NAMES }).first();
}

/** Пункт бизнеса в открытом списке переключателя. */
export function companyOption(page: Page, name: string): Locator {
  const exact = new RegExp(`^\\s*${esc(name)}\\s*$`);
  return page.getByRole('menuitem', { name: exact })
    .or(page.getByRole('menuitemradio', { name: exact }))
    .or(page.getByRole('option', { name: exact }))
    .first();
}

/** Все пункты бизнесов в открытом списке переключателя. */
export function companyOptions(page: Page): Locator {
  return page.getByRole('menuitem').or(page.getByRole('menuitemradio')).or(page.getByRole('option'));
}

export async function expectSelected(page: Page, name: string) {
  await expect(companySwitcher(page), `в шапке выбран «${name}»`).toHaveText(new RegExp(`^\\s*${esc(name)}\\s*$`), { timeout: 30_000 });
}

export async function openSwitcher(page: Page) {
  await companySwitcher(page).click();
  await expect(companyOption(page, TEST_COMPANY.name)).toBeVisible();
}

export async function switchTo(page: Page, name: string) {
  const current = (await companySwitcher(page).innerText()).trim();
  if (current === name) return;
  await openSwitcher(page);
  await companyOption(page, name).click();
  await expectSelected(page, name);
}

/** Вернуть бизнес «test»: переключателем (если выбран другой) и в localStorage. */
export async function restoreTest(page: Page) {
  if (page.isClosed()) return;
  if (!/\/(dashboard|jobs|customers)/i.test(page.url())) await page.goto('/dashboard');
  await expect(companySwitcher(page)).toBeVisible({ timeout: 30_000 });
  await switchTo(page, TEST_COMPANY.name);
  await page.evaluate((id) => window.localStorage.setItem('selected-company-id', id), TEST_COMPANY.id);
  expect(await page.evaluate(() => window.localStorage.getItem('selected-company-id')), 'selected-company-id = test').toBe(TEST_COMPANY.id);
}

/** Поле поиска списка (/jobs — «Search jobs...», /customers — «Search ...»). */
export const searchBox = (page: Page): Locator => page.getByPlaceholder(/^Search/i).first();

/** /customers → список загрузился (есть строка таблицы). */
export async function openClients(page: Page) {
  await page.goto('/customers');
  await expect(page.locator('main tbody tr').first(), 'список клиентов загрузился').toBeVisible({ timeout: 30_000 });
}

export async function search(page: Page, text: string) {
  const box = searchBox(page);
  await box.fill(text);
  await expect(box).toHaveValue(text);
}

/** /jobs → список загружен (есть хотя бы одна работа JOB-…). */
export async function openJobs(page: Page) {
  await page.goto('/jobs');
  await expect(page.locator('main')).toContainText(/JOB-\d{4}/, { timeout: 30_000 });
}

/** Код первой работы в таблице — «якорь»: после поиска он должен пропасть (доказательство, что фильтр применился). */
export async function firstJobCode(page: Page, exclude: string): Promise<string> {
  const codes = (await page.locator('tbody tr').allInnerTexts())
    .map((t) => t.match(/JOB-\s*(\d{4})/)?.[1])
    .filter((n): n is string => !!n)
    .map((n) => `JOB-${n}`)
    .filter((c) => c !== exclude);
  expect(codes.length, 'в списке есть другие работы').toBeGreaterThan(0);
  return codes[0];
}

/** Строка работы в таблице по коду (JOB-1036 переносится в ячейке как «JOB-\n1036»). */
export function jobRow(page: Page, code: string): Locator {
  const [prefix, num] = code.split('-');
  return page.locator('tr', { hasText: new RegExp(`${prefix}-\\s*${num}`) }).first();
}
